rep("function playerPool(){const drafted=draftedSet();const vm=valueMap();let list=Object.entries(state.players).map(([id,p])=>({id,p,v:vm[id]})).filter(x=>x.p&&['QB','RB','WR','TE'].includes(x.p.position)&&!drafted.has(x.id));if(state.rookiesOnly)list=list.filter(x=>isRookie(x.p));if(state.filter!=='ALL')list=list.filter(x=>x.p.position===state.filter);if(state.search)list=list.filter(x=>`${x.p.first_name||''} ${x.p.last_name||''}`.toLowerCase().includes(state.search));list.sort((a,b)=>(b.v?.value||0)-(a.v?.value||0));return list}", "function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'')}\nfunction fpMap(){const m={};Object.entries(state.fp.rankings||{}).forEach(([pos,a])=>a.forEach(x=>m[norm(x.name)]={...(m[norm(x.name)]||{}),rank:x.rank,tier:x.tier,pos}));Object.entries(state.fp.projections||{}).forEach(([pos,a])=>a.forEach(x=>m[norm(x.name)]={...(m[norm(x.name)]||{}),projection:x.points_half,pos}));return m}\nfunction trendMap(){const m={};(state.watch.history||[]).forEach(x=>{const a=x.message?.match(/^(.+?) \\([^)]*\\).*trending ([+-]?\\d+)/)||x.message?.match(/^(.+?) is now trending ([+-]?\\d+)/);if(a)m[norm(a[1])]=Number(a[2])});return m}\nfunction playerPool(){const drafted=draftedSet(),rostered=rosteredSet(),vm=valueMap(),fm=fpMap(),tm=trendMap();let list=Object.entries(state.players).map(([id,p])=>{const name=`${p.first_name||''} ${p.last_name||''}`.trim();return{id,p,v:vm[id],fp:fm[norm(name)]||{},trend:tm[norm(name)]||0,name,source:'Sleeper'}}).filter(x=>x.p&&['QB','RB','WR','TE'].includes(x.p.position)&&!drafted.has(x.id)&&!rostered.has(x.id));const year=Number(state.draft?.season||0);(state.prospects.players||[]).filter(x=>Number(x.draft_year)===year).forEach(x=>list.push({id:`prospect:${x.prospect_id||norm(x.name)}`,p:{first_name:x.name,last_name:'',position:x.position,team:x.school,years_exp:0},v:x.market_value?{value:x.market_value}:null,fp:{tier:x.tier||null,projection:x.projection||null},trend:x.trend_30d||0,name:x.name,source:'Prospect file',prospect:x}));if(state.rookiesOnly)list=list.filter(x=>isRookie(x.p));if(state.filter!=='ALL')list=list.filter(x=>x.p.position===state.filter);if(state.search)list=list.filter(x=>x.name.toLowerCase().includes(state.search));list=list.filter(x=>Number(x.v?.value)>0);list.sort((a,b)=>(b.v?.value||0)-(a.v?.value||0));return list}")
rep("function scorePlayer(x,index){const value=x.v?.value||Math.max(1,2500-index*25);const valueNorm=Math.min(100,Math.round(value/85));const fit=needScore(x.p.position);const liquidity=['QB','WR'].includes(x.p.position)?82:x.p.position==='RB'?72:65;const risk=isRookie(x.p)?45:35;const score=Math.round(valueNorm*.55+fit*.25+liquidity*.15+(100-risk)*.05);return{score,fit,value,liquidity,risk}}", "function formatContext(){const rp=state.league?.roster_positions||[];return{sf:rp.includes('SUPER_FLEX'),tep:Number(state.league?.scoring_settings?.bonus_rec_te||0)>0}}\nfunction scorePlayer(x,index){const value=Number(x.v?.value||0),ctx=formatContext();const valueNorm=Math.min(100,Math.round(value/85));const fit=needScore(x.p.position);const format=(ctx.sf&&x.p.position==='QB'?14:0)+(ctx.tep&&x.p.position==='TE'?8:0);const trend=Math.max(-8,Math.min(8,x.trend/20));const projection=x.fp?.projection?Math.min(8,x.fp.projection/45):0;const declaration=x.prospect?.declaration_status==='declared'?6:x.prospect?.declaration_status==='expected'?2:x.prospect?-6:0;const liquidity=['QB','WR'].includes(x.p.position)?82:x.p.position==='RB'?72:65;const risk=isRookie(x.p)?45:35;const score=Math.round(valueNorm*.50+fit*.17+liquidity*.10+(100-risk)*.04+format+trend+projection+declaration);const confidence=Math.round([value,x.fp?.rank||x.fp?.projection,x.source,x.prospect?x.prospect.declaration_status:true].filter(Boolean).length/4*100);return{score:Math.max(0,Math.min(100,score)),fit,value,liquidity,risk,confidence}}")
